interface MervExplicitLocalReportOptions {
    /**
     * Override report root directory. When omitted, uses {@code merv.report.folder} from {@code merv.properties}
     * (resolved from {@link cwd}).
     */
    reportRoot?: string;
    /** Override suite title; default {@code merv.regression_suite} from properties. */
    suiteTitle?: string;
    /** Directory to start searching for {@code merv.properties} (default {@link process.cwd}). */
    cwd?: string;
}
/**
 * Build a MERV local run folder (**{@code json/merv-report.json}**, **{@code html/*.html}**) without registering the
 * Playwright reporter. Use from scripts, non-Playwright runners, or manual pipelines.
 *
 * @example
 * ```ts
 * import { MervExplicitLocalReport } from 'merv-client';
 *
 * const run = MervExplicitLocalReport.open();
 * const shot = run.copyScreenshotFromFile('/tmp/capture.png', 'login-step');
 * run.addTestCase({
 *   testcaseName: 'Checkout flow',
 *   status: 'PASSED',
 *   startTime: new Date().toISOString(),
 *   endTime: new Date().toISOString(),
 *   executionMachine: os.hostname(),
 *   testSteps: [
 *     {
 *       teststepName: 'Open cart',
 *       stepType: 'CUSTOM',
 *       status: 'PASSED',
 *       startTime: new Date().toISOString(),
 *       endTime: new Date().toISOString(),
 *       screenshots: shot ? [shot] : [],
 *     },
 *   ],
 * });
 * run.finalize();
 * ```
 */
declare class MervExplicitLocalReport {
    readonly paths: LocalRunPaths;
    private readonly suiteTitle;
    private readonly suiteStartMs;
    private testCases;
    private constructor();
    /**
     * Creates a new timestamped run folder under the configured report root and returns a session.
     */
    static open(opts?: MervExplicitLocalReportOptions): MervExplicitLocalReport;
    /** Append one testcase (deep-copied). Call {@link persist} or {@link finalize} to write files. */
    addTestCase(tc: MervTestCase): void;
    /** Replace the full testcase list. */
    setTestCases(cases: MervTestCase[]): void;
    /** Copy an image file into this run’s {@code screenshots/} folder; returns a run-relative path for {@link MervTestStep.screenshots}. */
    copyScreenshotFromFile(sourcePath: string, baseName: string): string | null;
    /** Copy an in-memory PNG (or other image buffer) into {@code screenshots/}. */
    copyScreenshotFromBuffer(body: Buffer, baseName: string): string | null;
    /**
     * Writes {@code json/merv-report.json}. While {@code running: true}, refreshes the index
     * manifest so the dashboard / live page pick up new cases and steps (same as Playwright reporter).
     * When {@code running: false}, also writes the final embedded suite HTML.
     */
    persist(running?: boolean): void;
    /** Writes final JSON/HTML with {@code running: false} and refreshes {@code index.html} under the report root. */
    finalize(): void;
    private buildReport;
}

/**
 * Filesystem file reference for {@link MervReport.testdata} (Java {@code File} equivalent).
 */
declare class MervReportFile {
    readonly filePath: string;
    constructor(filePath: string);
}
/**
 * User-facing MERV report API for custom steps.
 *
 * <p>Custom step helpers exposed to test authors:</p>
 * <ul>
 *   <li>{@link #info}</li>
 *   <li>{@link #testdata} (string or {@link MervReportFile})</li>
 *   <li>{@link #validation}</li>
 * </ul>
 *
 * <p>Session lifecycle: {@link #open}, {@link #createTest}, {@link #finalize}.</p>
 */
declare class MervReport {
    private readonly engine;
    private constructor();
    static open(opts?: MervExplicitLocalReportOptions): Promise<MervReport>;
    createTest(testName: string, desc: string): Promise<void>;
    finalize(): Promise<void>;
    /**
     * Local mode only: flush current cases/steps to disk ({@code running: true} by default).
     * Steps already auto-persist; call this only if you mutate state outside the step helpers.
     */
    persist(running?: boolean): void;
    info(str: string): Promise<void>;
    testdata(stepName: string, data: string): Promise<void>;
    testdata(stepName: string, testData: MervReportFile): Promise<void>;
    validation(stepName: string, expected: string, actual: string): Promise<void>;
    validation(stepName: string, expected: string, actual: string, screenshot: boolean): Promise<void>;
}

/**
 * {@code merv.step.allowed} — high-level step categories for report filtering.
 *
 * Example: {@code merv.step.allowed=info,hook,assertion,action}
 *
 * Categories not listed are omitted from the MERV report.
 */
type MervStepAllowedCategory = 'info' | 'hook' | 'assertion' | 'action';
/**
 * Parse {@code merv.step.allowed=info,hook,assertion,action}.
 * Returns {@code null} when unset/empty (legacy filtering applies).
 */
declare function parseAllowedStepCategories(raw: string | undefined): MervStepAllowedCategory[] | null;
/** Map a report {@code stepType} to an allowed category, or {@code null} if uncategorized. */
declare function resolveStepAllowedCategory(stepType: string | undefined | null): MervStepAllowedCategory | null;
/** True when this step should appear given an active {@code merv.step.allowed} list. */
declare function isStepCategoryAllowed(stepType: string | undefined | null, allowed: readonly MervStepAllowedCategory[] | null | undefined): boolean;

type MervMode = 'local' | 'server';
/** Auth and suite bootstrap for {@code merv.local=false} (merv-api). */
interface MervServerAuthConfig {
    baseUrl: string;
    apiKey?: string;
    username?: string;
    password?: string;
    parentHierarchy?: string;
    sprint?: string;
    tags?: string[];
    appendSuite?: string;
    appendSuiteAlias?: string;
}
interface MervConfig {
    mode: MervMode;
    reportRoot: string;
    suiteTitle: string;
    server: MervServerAuthConfig | null;
    screenshot: boolean;
    /**
     * When true ({@code merv.video=true}), Playwright actions are captured as highlighted frames and
     * stitched into a per-testcase video (~1s per frame). Step PNGs in the report still require
     * {@code merv.screenshot=true}.
     */
    video: boolean;
    /** When true, report includes every Playwright step category; when false (default), only API actions and expects. */
    debug: boolean;
    /**
     * Normalized uppercase tokens (e.g. VALIDATION_STEP, INFO, DATA_STEP). When not {@link debug}, steps whose
     * {@code stepType} is in this list are shown in addition to PLAYWRIGHT_API and EXPECT (see {@code formatMervStepTitle}).
     */
    extraReportStepTypes: readonly string[];
    /**
     * When set via {@code merv.step.allowed}, only these high-level categories appear in the report
     * ({@code info}, {@code hook}, {@code assertion}, {@code action}). Overrides the default/debug allowlists.
     * {@code null} means the property is unset (legacy filtering).
     */
    allowedStepCategories: readonly MervStepAllowedCategory[] | null;
    /**
     * When false (default), a failed MERV assertion ({@code addValidationStep} mismatch) or {@code addCustomStep(..., 'FAILED')}
     * throws after recording the step so Playwright marks the test failed. Set {@code merv.plugin_assertion_soft=true} to only
     * record in the report without failing the run.
     */
    pluginAssertionSoft: boolean;
    /** From {@code merv.execution.parallel}; when true, suite is not auto-marked COMPLETED on last session. */
    executionParallel: boolean;
    /** When true (default), auto-register MERV Chai plugin when {@code chai} is installed ({@code merv.chai=false} to disable). */
    chaiIntegration: boolean;
    /**
     * When true, Cucumber (or other hosts) should wrap Playwright {@code Page} so goto/click/fill become
     * {@code PLAYWRIGHT_API} rows ({@code merv.playwright.actions=true}). Used by {@code merv-client-playwright}.
     */
    playwrightActions: boolean;
    /** Directory containing {@code merv.properties} (project root for coordination files). */
    projectRoot: string;
    /** When true (default), local runs also write {@code merv-report-upload.zip} for MERV UI import. */
    zipExport: boolean;
    /**
     * When true, local finalize also writes {@code emailable-report.html} at the run folder root
     * and report root ({@code merv.emailable.html=true}).
     */
    emailableHtml: boolean;
    /**
     * When true (default), the Playwright MERV reporter writes step lines to {@code log/*.ndjson}
     * (for Merv-Logs). Set {@code merv.logger.reporter.steps=false} when specs import
     * {@code merv-client-playwright/test} to avoid duplicate action lines.
     */
    reporterStepLogs: boolean;
}
/** Stable project root for cross-worker coordination (same path in every Playwright worker). */
declare function resolveMervProjectRoot(cwd?: string): string;
declare function loadMervConfig(cwd?: string): MervConfig;

