/**
 * Minimal Playwright-shaped types so core does not depend on a specific
 * {@code @playwright/test} version (framework packages supply the real types).
 */
interface MervPageLike {
    screenshot(options?: Record<string, unknown>): Promise<Buffer>;
}
interface MervTestInfoLike {
    /**
     * Playwright {@code TestInfo.attach} — kept loose so real {@code TestInfo} assigns cleanly.
     */
    attach(name: string, options?: Record<string, unknown>): Promise<void>;
    /** Playwright {@code TestInfo.title} (optional — used for Merv-Logs context). */
    title?: string;
    /**
     * Playwright {@code TestInfo.titlePath} — method in some versions, {@code string[]} property in others.
     */
    titlePath?: (() => string[]) | string[];
    project?: {
        name?: string;
    };
}

/**
 * Mirrors {@code org.teche.merv.client.plugin.AutomationTool} for use with
 * {@link MervPlaywright.setAutomationToolObject}.
 */
declare const AutomationTool: {
    readonly SELENIUM: "SELENIUM";
    readonly PLAYWRIGHT: "PLAYWRIGHT";
    readonly PROTRACTOR: "PROTRACTOR";
    readonly APPIUM: "APPIUM";
    readonly WEBDRIVERIO: "WEBDRIVERIO";
    readonly CYPRESS: "CYPRESS";
    readonly AUTO: "AUTO";
};
type AutomationToolName = (typeof AutomationTool)[keyof typeof AutomationTool];

interface MervPlaywrightScreenshotHookParams {
    testStepId?: string;
    result?: {
        status?: string;
        message?: string;
    };
}
interface MervPlaywrightScreenshotOptions {
    /** Defaults to the page bound via {@link setAutomationToolObject}. */
    page?: MervPageLike | null;
    screenshotEnabled?: boolean;
    cwd?: string;
}
/**
 * Per-worker binding (same idea as Java {@code ThreadLocal} on the Playwright worker process).
 * Call {@link MervPlaywright.setAutomationToolObject} from a hook/fixture, or use {@code extendTestWithMervScreenshots}
 * (sets {@link AutomationTool.PLAYWRIGHT} + page while {@code merv.screenshot=true}).
 *
 * State is stored on {@code globalThis} so Cucumber hooks ({@code require('merv-client')}) and the MERV formatter
 * ({@code merv-client/cucumber-formatter} ESM bundle) share one binding.
 */
declare class MervPlaywright {
    /**
     * @param tool — pass {@code null} to clear (same as Java overload clearing thread locals).
     * @param driverOrPage — for {@link AutomationTool.PLAYWRIGHT}, a {@link MervPageLike}; other tools reserved / future use.
     */
    static setAutomationToolObject(tool: AutomationToolName | null, driverOrPage: unknown): void;
    static getAutomationTool(): AutomationToolName | null;
    /** Untyped handle (WebDriver in Java Selenium; here usually {@link MervPageLike}). */
    static getAutomationToolObject(): unknown;
    /** Returns the bound Playwright page when tool is {@link AutomationTool.PLAYWRIGHT}. */
    static getPage(): MervPageLike | null;
    static clear(): void;
    /**
     * Stash a step PNG for the Cucumber formatter.
     * Prefer {@code testStepId} from the {@code AfterStep} hook so concurrent steps do not overwrite each other.
     */
    static stashStepScreenshot(body: Buffer, testStepId?: string): void;
    /**
     * Consumed by {@link MervCucumberSession} when a step finishes.
     * Call synchronously in the formatter before any {@code await} to avoid races.
     */
    static consumeStepScreenshot(testStepId?: string): Buffer | null;
    /**
     * Call from Cucumber {@code AfterStep} while the Playwright {@code page} is still open.
     * Stashes a PNG keyed by {@code testStepId} for the MERV formatter.
     *
     * When {@code merv.screenshot=true}, captures executed steps (not skipped). Failed steps always capture.
     * Uses the bound page from {@link setAutomationToolObject} unless {@code options.page} is passed.
     */
    static screenshot(hookParams: MervPlaywrightScreenshotHookParams, options?: MervPlaywrightScreenshotOptions): Promise<void>;
}

